   233	    ? fullEvents.reduce((sum, event) => sum + (event.tokenCount ?? 0), 0)
   234	    : null;
   235	  const summary = {
   236	    readCount: fullEvents.length,
   237	    tokenCount,
   238	  };
   239	  const normalizedDigestEvents = digestEvents.sort((a, b) =>
